INSERT INTO posts (board_id, user_id, title, content, view_count, created_at) VALUES ((SELECT id FROM boards WHERE name='รีวิวร้านอาหาร' LIMIT 1), (SELECT id FROM users WHERE email='demo020@demo.boardkub.local'), 'รีวิวข้าวซอยใกล้โรงอาหารกลาง ราคานักศึกษา', 'ไปกินมาเมื่อวาน จานละ 50 บาท รสชาติดี ช่วงเที่ยงคิวยาว แนะนำไปก่อน 11 โมง
INSERT INTO posts (board_id, user_id, title, content, view_count, created_at) VALUES ((SELECT id FROM boards WHERE name='ของหาย-ของเจอ' LIMIT 1), (SELECT id FROM users WHERE email='demo071@demo.boardkub.local'), '[ตามหา] บัตรนักศึกษาหายแถวป้ายรถตู้', 'ทำบัตรนักศึกษาหายเมื่อวานช่วงเย็น ใครเจอติดต่อในกระทู้นี้ได้เลย ขอบคุณมาก', 44, @now - INTERVAL 302 HOUR);
